code.cpp:
class Solution {
public:
    int findClosestNumber(vector<int>& nums) {
        int best = nums[0];
        for (int x : nums) {
            if (abs(x) < abs(best)) {
                best = x;
            } else if (abs(x) == abs(best)) {
                best = max(best, x);
            }
        }
        return best;
    }
};
